      if (!res.ok) return;
      const data = await res.json();
      setOnboarding((prev) => {
        if (!prev) return prev;
        return {
          ...prev,
          status: data.status,
          metadata: data.metadata,
        };
      });
    } catch {
      // ignore polling errors
    }
  }, []);

  // Poll for status updates every 2 seconds when onboarding is active
  useEffect(() => {
    if (!onboarding?.runId) return;
    const metaStatus = onboarding.metadata?.status;
    // Stop polling if completed or failed
    if (onboarding.status === "COMPLETED" || onboarding.status === "FAILED" || onboarding.status === "CANCELED") return;

